WITH customer_stats AS (SELECT customer_id, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, COUNT(DISTINCT device) AS unique_devices FROM sessions GROUP BY customer_id) SELECT customers.id, customers.age, customer_stats.browser_list, customer_stats.unique_devices FROM customers LEFT OUTER JOIN customer_stats ON customers.id = customer_stats.customer_id WHERE customer_stats.unique_devices > 3;
